//! 🔐️ Invalid consuming decoder receipts remain in their original receiving slot.
use crate::ValueError;
use semio_framework_test_fixtures::fixture_text;
fn fixture()->serde_json::Value{serde_json::from_str(fixture_text!("../../🫴️recipient/🔁️continuation/🧪️tests/🧫️fixtures/🔣️.json")).unwrap()}
#[test]fn native_local_original_invalid_decode_receipt_is_not_consumed(){let law=fixture();let mut recipient=super::NativeDecodeRetirementRecipient::new();let mut observer=|_|true;let mut native=super::NativeDecodeControl::new(law["maximumNativeBytes"].as_u64().unwrap()as usize,&mut observer);native.charge(law["initialBytes"].as_u64().unwrap()as usize).unwrap();let mut receipt=native.pause().unwrap();receipt.completed=law["invalidReceipt"]["completed"].as_u64().unwrap()as usize;receipt.total=law["invalidReceipt"]["total"].as_u64().unwrap()as usize;let mut receipt=super::NativeRetirementDecodeContinuation{receipt:Some(receipt),recipient:&mut recipient};let before=receipt.owned_bytes();let mut accepted=|_|true;let error=receipt.decode::<(),ValueError>(&mut accepted,|_|Ok(())).unwrap_err();assert_eq!(error.context.unwrap().kind.as_str(),law["invalidReceipt"]["kind"].as_str().unwrap());assert_eq!(receipt.owned_bytes(),before);let(detached,_)=receipt.detach();assert_eq!(detached.owned_bytes(),before);}
